{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "Before taking any action that updates the database (cancel, modify, return, exchange), you must list the action details and obtain explicit user confirmation (yes) to proceed.",
      "requirement": "The assistant must explicitly confirm with the user that all action details (e.g., items to exchange, new items, payment method) are correct before proceeding with the exchange."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "You should not make up any information or knowledge or procedures not provided by the user or the tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must only communicate information directly derived from the user's input or tool responses, without adding assumptions or subjective commentary."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q19",
      "policy_quote": "An order can only be exchanged if its status is 'delivered', and you should check its status before taking the action.",
      "requirement": "The assistant must verify that the order status is 'delivered' before proceeding with the exchange."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q19",
      "policy_quote": "For a delivered order, each item can be exchanged to an available new item of the same product but of different product option. There cannot be any change of product types, e.g., modify shirt to shoe.",
      "requirement": "The exchanged item must be of the same product type (Wireless Earbuds) but can have different product options (e.g., water resistance level)."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q19",
      "policy_quote": "The user must provide a payment method to pay or receive refund of the price difference. If the user provides a gift card, it must have enough balance to cover the price difference.",
      "requirement": "The payment method (gift card) must be valid and capable of covering the price difference (refund or payment) for the exchange."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q19",
      "policy_quote": "After user confirmation, the order status will be changed to 'exchange requested', and the user will receive an email regarding how to return items.",
      "requirement": "The assistant must ensure explicit user confirmation (yes) before executing the exchange tool call."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q15",
      "policy_quote": "You can only help one user per conversation (but you can handle multiple requests from the same user), and must deny any requests for tasks related to any other user.",
      "requirement": "The assistant must ensure the exchange action is performed only for the authenticated user (Aarav Anderson) and no other user."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q15",
      "policy_quote": "You should at most make one tool call at a time, and if you take a tool call, you should not respond to the user at the same time.",
      "requirement": "The assistant must not send a message to the user while the exchange tool call is in progress."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q19",
      "policy_quote": "For a delivered order, return or exchange can be only done once by the agent.",
      "requirement": "The assistant must ensure that no prior exchange or return action has been taken on this order before proceeding."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q18",
      "policy_quote": "This action can only be called once, and will change the order status to 'pending (items modified)' or 'exchange requested'. The agent will not be able to modify or cancel the order anymore.",
      "requirement": "The assistant must ensure that the exchange action is only called once for this order, and the order status will be updated to 'exchange requested' after confirmation."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q15",
      "policy_quote": "You should transfer the user to a human agent if and only if the request cannot be handled within the scope of your actions.",
      "requirement": "If the exchange cannot be completed due to any policy or system constraints, the assistant must transfer the user to a human agent."
    }
  ]
}
